fn reverseWords(sentence: Text) -> Text {
  let words = sentence.split(" ")
  var res = ""
  for w in words {
    if res == "" {
      res = w
    } else {
      res = w + " " + res
    }
  }
  return res
}

test "reverseWords function" {
  expect reverseWords("hello world") == "world hello"
  expect reverseWords("one") == "one"
  expect reverseWords("") == ""
  expect reverseWords("a b c") == "c b a"
}

fn fizzbuzz(n: Number) -> Text {
    if n % 3 == 0 and n % 5 == 0 {
        return "FizzBuzz"
    }
    if n % 3 == 0 {
        return "Fizz"
    }
    if n % 5 == 0 {
        return "Buzz"
    }
    return n.to_text()
}

test "fizzbuzz function" {
  expect fizzbuzz(1) == "1"
  expect fizzbuzz(3) == "Fizz"
  expect fizzbuzz(5) == "Buzz"
  expect fizzbuzz(15) == "FizzBuzz"
  expect fizzbuzz(16) == "16"
}

fn is_prime(n: Number) -> Bool {
    if n < 2 { return false }
    var i = 2
    while i * i <= n {
        if n % i == 0 { return false }
        i = i + 1
    }
    return true
}

test "prime tests" {
  expect is_prime(2) == true
  expect is_prime(3) == true
  expect is_prime(4) == false
  expect is_prime(5) == true
  expect is_prime(9) == false
}

fn maxInList(lst: Number[]) -> Number {
    if lst.length() == 0 {
        return 0
    }
    var max = lst[0]
    for x in lst {
        if x > max {
            max = x
        }
    }
    return max
}

test "the ask's own tests" {
  expect maxInList([1, 3, 2]) == 3
  expect maxInList([]) == 0
  expect maxInList([5]) == 5
  expect maxInList([-10, -5, -20]) == -5
}

